def transform(grid):
    """Restore the cyclic 1..9 grid with its repeated diagonal."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if r == 0:
                value = (c + 1) % 9 + 1
            elif c == 0:
                value = 3
            elif c == r:
                value = (c + 1) % 9 + 1
            else:
                value = (c + 2) % 9 + 1
            row.append(value)
        out.append(row)
    return out
